import { useState, useEffect, useCallback } from 'react';
import axios from 'utils/axios';
import { API_PATHS } from 'utils/api-constants';

/**
 * useLookups Hook
 * Standardized way to fetch master data (Departments, Designations, etc.)
 * Usage: const { departments, designations, loading } = useLookups(['DEPARTMENTS', 'DESIGNATIONS']);
 */
export const useLookups = (lookupTypes = []) => {
  const [lookups, setLookups] = useState({
    loading: true,
    error: null
  });

  const fetchLookups = useCallback(async () => {
    setLookups(prev => ({ ...prev, loading: true }));
    const results = {};
    
    try {
      const settledResults = await Promise.allSettled(
        lookupTypes.map(async (type) => {
          let path = API_PATHS.HRM[type] || API_PATHS.QMS[type] || API_PATHS.SM[type] || API_PATHS.NPD[type];
          if (!path) {
            console.warn(`Lookup type "${type}" not found in API_PATHS`);
            return null;
          }
          // SOP: For AUDIT_TYPE lookup, fetch from the /active unpaginated endpoint to get all active options
          if (type === 'AUDIT_TYPE') {
            path = `${path}/active`;
          }
          const response = await axios.get(path);
          const data = response.data;
          let key = type.toLowerCase().replace(/_([a-z])/g, (g) => g[1].toUpperCase());
          if (!key.endsWith('s')) key += 's';
          return { key, data: Array.isArray(data) ? data : (data && Array.isArray(data.content) ? data.content : []) };
        })
      );
      
      settledResults.forEach(result => {
        if (result.status === 'fulfilled' && result.value) {
          results[result.value.key] = result.value.data;
        }
      });
      console.log('useLookups resolved results:', results);
      
      setLookups({
        ...results,
        loading: false,
        error: null
      });
    } catch (err) {
      console.error('Failed to fetch lookups:', err);
      setLookups(prev => ({ ...prev, loading: false, error: err }));
    }
  }, [JSON.stringify(lookupTypes)]);

  useEffect(() => {
    if (lookupTypes.length > 0) {
      fetchLookups();
    } else {
      setLookups(prev => ({ ...prev, loading: false }));
    }
  }, [fetchLookups]);

  return lookups;
};

export default useLookups;
