import PropTypes from 'prop-types';
import {
  Box, Table, TableBody, TableCell, TableContainer, TableHead,
  TableRow, Paper, IconButton, Tooltip, TablePagination, Stack,
  Chip, Typography, useTheme, alpha
} from '@mui/material';
import { useColorScheme } from '@mui/material/styles';
import { IconEdit, IconTrash } from '@tabler/icons-react';
import { format } from 'date-fns';
import { useSelector, useDispatch } from 'react-redux';
import React, { useMemo, useEffect, useState, useRef } from 'react';
import { setTableConfig } from 'store/slices/search';
import {
  tableContainerSx, tableHeadCellSx, getTableRowSx,
  tableActionEditSx, tableActionDeleteSx, getStatusChipSx
} from './BOSStyles';
import { getPhotoUrl, resolveNestedValue } from './BOSUtils';
import { IconUser } from '@tabler/icons-react';
import { Avatar } from '@mui/material';

/**
 * BOS DataTable — SOP #2, #7, #8, #12, #15, #16
 * Universal scrollable datatable for all BOS master pages.
 */
export default function BOSDataTable({
  columns,
  data,
  rows: rowsProp,
  loading,
  onEditRow,
  onDeleteRow,
  onDoubleClickRow,
  showActions: showActionsProp = true,
  actionColumn,
  selectable = false,
  onSelectionChange,
  totalCount,
  page = 0,
  size = 10,
  onPageChange,
  onSizeChange,
  footerActions,
  onClickRow,
  selectedRowId,
  renderCell,
  sx = {},
  id,
  onRowMouseEnter,
  onRowMouseLeave,
  onRowMouseMove,
  disableSearchFilter = false,
  disableTableConfig = false
}) {
  const rows = data || rowsProp || [];
  console.log('[BOSDataTable] Rendering with rows:', rows.length);
  const dispatch = useDispatch();
  const [localSelectedId, setLocalSelectedId] = useState(null);
  const lastConfigRef = useRef(null);

  useEffect(() => {
    if (columns && rows) {
      // Rule 1 extension: Extract unique values from rows for each column to provide dropdown options
      const columnsWithData = columns.map(col => {
        if (col.id === 'index' || col.id === 'photo' || col.id === 'actions') return col;
        
        const uniqueValues = [...new Set(rows.map(r => resolveNestedValue(col.id, r)))]
          .filter(v => v !== undefined && v !== null && v !== '' && typeof v !== 'object' && typeof v !== 'function')
          .map(v => ({ value: v, label: String(v) }));

        return { ...col, options: uniqueValues };
      });

      // Only dispatch serializable metadata to Redux
      const serializableConfig = columnsWithData
        .filter(c => c.id !== 'index' && c.id !== 'photo' && c.id !== 'actions')
        .map(c => ({
          id: c.id,
          label: typeof c.label === 'string' ? c.label : String(c.id).toUpperCase(),
          options: c.options || []
        }));

      // Serialize safely to avoid redundant dispatches
      const serialized = JSON.stringify(serializableConfig);
      
      if (!disableTableConfig && lastConfigRef.current !== serialized) {
        lastConfigRef.current = serialized;
        dispatch(setTableConfig(serializableConfig));
      }
    }
  }, [columns, rows, dispatch, disableTableConfig]);

  useEffect(() => {
    return () => {
      if (!disableTableConfig) {
        dispatch(setTableConfig(null));
      }
    };
  }, [dispatch, disableTableConfig]);
  const theme = useTheme();
  const { colorScheme } = useColorScheme();
  const isDark = colorScheme === 'dark';
  const baseRowSx = getTableRowSx(isDark);

  const showActions = useMemo(() => {
    if (showActionsProp === false) return false;
    return Boolean(onEditRow || onDeleteRow || actionColumn);
  }, [showActionsProp, onEditRow, onDeleteRow, actionColumn]);

  const searchQuery = useSelector((state) => state.search?.query || '');
  const globalFilters = useSelector((state) => state.search?.filters || {});

  const formatDate = (d) => {
    if (!d) return '-';
    try { 
      const dateObj = new Date(d);
      if (isNaN(dateObj.getTime())) return String(d);
      return format(dateObj, 'dd/MM/yyyy'); 
    } catch { 
      return '-'; 
    }
  };

  const getCellDisplayValue = (col, row, idx) => {
    if (col.id === 'updatedBy' || col.id === 'updated_by') {
      const hasUpdate = row['updatedAt'] || row['updated_at'] || row['updatedDate'] || row['updated_date'];
      if (!hasUpdate) return '-';
    }

    let val = resolveNestedValue(col.id, row);
    
    if (val === undefined || val === null) {
      // 1. Standard camelCase to snake_case (e.g. updatedBy -> updated_by)
      const snakeCaseId = col.id.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
      val = row[snakeCaseId];
      
      // 2. Audit-Specific Fallbacks (The "Big 4" + User variants)
      if (val === undefined || val === null || val === '') {
        if (col.id === 'createdDate') val = row['createdAt'] || row['created_at'];
        if (col.id === 'updatedDate') val = row['updatedAt'] || row['updated_at'];
        if (col.id === 'createdUser') val = row['createdBy'] || row['created_by'] || row['created_user'];
        if (col.id === 'updatedUser') val = row['updatedBy'] || row['updated_by'] || row['updated_user'];
        if (col.id === 'createdBy') val = row['createdUser'] || row['created_by'] || row['created_user'];
        if (col.id === 'updatedBy') val = row['updatedUser'] || row['updated_by'] || row['updated_user'];
      }
    }

    if (col.id === 'index') return String((page * size) + (idx + 1));

    if (col.id === 'status' || col.id === 'accountStatus') {
      let statusText = 'Inactive';
      if (val === 1 || val === 'Active' || val === 'ACTIVE') statusText = 'Active';
      else if (val === 'Suspended' || val === 'SUSPENDED') statusText = 'Suspended';
      else if (val === 0 || val === 'Inactive' || val === 'INACTIVE' || val === 'InActive' || val === 'In Active') statusText = 'Inactive';
      else if (val !== null && val !== undefined && val !== '') statusText = String(val);
      return statusText;
    }

    const isDateField = (col.id.toLowerCase().includes('date') || 
                        col.id.endsWith('At') || 
                        col.id.endsWith('_at') || 
                        col.id === 'entryDate' ||
                        col.id === 'invoiceDate') &&
                        !col.id.toLowerCase().includes('by');
    
    // Explicitly exclude false positives like 'state' or 'category'
    const isFalsePositive = col.id.toLowerCase().includes('state') || col.id.toLowerCase().includes('category');

    if (isDateField && !isFalsePositive) {
      return formatDate(val);
    }
    
    // Handle Boolean values (Yes/No)
    if (typeof val === 'boolean') return val ? 'Yes' : 'No';
    
    if (typeof val === 'object' && val !== null) {
      return val.name || val.label || val.id || '-';
    }
    return (val !== null && val !== undefined && val !== '') ? String(val) : '-';
  };

  const filteredRows = useMemo(() => {
    if (!rows || rows.length === 0) return [];
    if (disableSearchFilter) return rows;

    return rows.filter((row, idx) => {
      // 1. Dynamic Filters from Search Popover
      if (globalFilters) {
        // Collect all base date keys that have start or end filters active
        const activeDateKeys = new Set();
        for (const key of Object.keys(globalFilters)) {
          if (key.endsWith('Start')) {
            activeDateKeys.add(key.slice(0, -5));
          } else if (key.endsWith('End')) {
            activeDateKeys.add(key.slice(0, -3));
          }
        }

        // Loop through all regular filters
        for (const [key, fVal] of Object.entries(globalFilters)) {
          if (fVal === undefined || fVal === null || fVal === '' || fVal === 'All') continue;
          
          // Skip start, end, and consider keys as they will be processed together
          if (key.endsWith('Start') || key.endsWith('End') || key.endsWith('Consider')) {
            continue;
          }

          const col = columns.find(c => c.id === key);
          if (!col && key !== 'status') continue; 

          let filterVal = String(fVal).toLowerCase().trim();
          const isDateField = (col && (col.id.toLowerCase().includes('date') || 
                              col.id.endsWith('At') || 
                              col.id.endsWith('_at') || 
                              col.id === 'entryDate' ||
                              col.id === 'invoiceDate') &&
                              !col.id.toLowerCase().includes('by'));
          
          if (isDateField && filterVal.match(/^\d{4}-\d{2}-\d{2}$/)) {
            try {
              const [y, m, d] = filterVal.split('-');
              filterVal = `${d}/${m}/${y}`;
            } catch {}
          }

          const displayVal = col ? getCellDisplayValue(col, row, idx).toLowerCase().trim() : String(row[key] || '').toLowerCase().trim();
          
          if (filterVal && !displayVal.includes(filterVal)) {
            return false;
          }
        }

        // Process active date range filters together
        for (const baseKey of activeDateKeys) {
          const col = columns.find(c => c.id === baseKey);
          const colId = col ? col.id : baseKey;

          const startVal = globalFilters[`${baseKey}Start`];
          const endVal = globalFilters[`${baseKey}End`];
          const considerVal = globalFilters[`${baseKey}Consider`] || 'Yes';

          if (!startVal && !endVal) continue;
          if (considerVal === 'No') continue;

          let cellVal = resolveNestedValue(colId, row);
          if (cellVal === undefined || cellVal === null || cellVal === '') {
            const snakeCaseId = colId.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
            cellVal = row[snakeCaseId];
            if (cellVal === undefined || cellVal === null || cellVal === '') {
              if (colId === 'createdDate' || colId === 'createdAt') cellVal = row['createdAt'] || row['created_at'];
              if (colId === 'updatedDate' || colId === 'updatedAt') cellVal = row['updatedAt'] || row['updated_at'];
              if (colId === 'createdUser') cellVal = row['createdBy'] || row['created_by'] || row['created_user'];
              if (colId === 'updatedUser') cellVal = row['updatedBy'] || row['updated_by'] || row['updated_user'];
              if (colId === 'createdBy') cellVal = row['createdUser'] || row['created_by'] || row['created_user'];
              if (colId === 'updatedBy') cellVal = row['updatedUser'] || row['updated_by'] || row['updated_user'];
            }
          }

          if (!cellVal || cellVal === '-') return false;

          try {
            const cellDate = new Date(cellVal);
            if (isNaN(cellDate.getTime())) return false;
            const cellDateMidnight = new Date(cellDate.getFullYear(), cellDate.getMonth(), cellDate.getDate());

            const startDate = startVal ? new Date(startVal) : null;
            const startDateMidnight = startDate && !isNaN(startDate.getTime()) ? new Date(startDate.getFullYear(), startDate.getMonth(), startDate.getDate()) : null;

            const endDate = endVal ? new Date(endVal) : null;
            const endDateMidnight = endDate && !isNaN(endDate.getTime()) ? new Date(endDate.getFullYear(), endDate.getMonth(), endDate.getDate()) : null;

            // Check boundaries
            let inBetween = true;
            if (startDateMidnight && cellDateMidnight < startDateMidnight) {
              inBetween = false;
            }
            if (endDateMidnight && cellDateMidnight > endDateMidnight) {
              inBetween = false;
            }

            if (!inBetween) return false;
          } catch {
            return false;
          }
        }
      }

      // 2. Global Query (Main text box)
      if (searchQuery) {
        const queryLower = searchQuery.toLowerCase();
        return columns.some((col) => {
          if (col.id === 'index' || col.id === 'photo' || col.id === 'actions') return false;
          const displayVal = getCellDisplayValue(col, row, idx).toLowerCase();
          return displayVal.includes(queryLower);
        });
      }

      return true;
    });
  }, [rows, searchQuery, globalFilters, columns, disableSearchFilter, page, size]);

  const paginatedRows = useMemo(() => {
    // If the rows are already sliced/paginated by the caller (i.e. rows.length <= size and totalCount is larger),
    // we should render them directly without slicing.
    if (totalCount !== undefined && totalCount > filteredRows.length && filteredRows.length <= size) {
      return filteredRows;
    }
    // Otherwise, do local pagination
    return filteredRows.slice(page * size, page * size + size);
  }, [filteredRows, page, size, totalCount]);

  const defaultRenderCell = (col, row, idx) => {
    if (col.render) return col.render(row, idx);
    
    if (col.id === 'updatedBy' || col.id === 'updated_by') {
      const hasUpdate = row['updatedAt'] || row['updated_at'] || row['updatedDate'] || row['updated_date'];
      if (!hasUpdate) return '-';
    }

    // ── DATA RESOLUTION (Supports camelCase, snake_case, and common audit fallbacks) ──
    let val = resolveNestedValue(col.id, row);
    
    if (val === undefined || val === null) {
      // 1. Standard camelCase to snake_case (e.g. updatedBy -> updated_by)
      const snakeCaseId = col.id.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
      val = row[snakeCaseId];
      
      // 2. Audit-Specific Fallbacks (The "Big 4" + User variants)
      if (val === undefined || val === null || val === '') {
        if (col.id === 'createdDate') val = row['createdAt'] || row['created_at'];
        if (col.id === 'updatedDate') val = row['updatedAt'] || row['updated_at'];
        if (col.id === 'createdUser') val = row['createdBy'] || row['created_by'] || row['created_user'];
        if (col.id === 'updatedUser') val = row['updatedBy'] || row['updated_by'] || row['updated_user'];
        if (col.id === 'createdBy') val = row['createdUser'] || row['created_by'] || row['created_user'];
        if (col.id === 'updatedBy') val = row['updatedUser'] || row['updated_by'] || row['updated_user'];
      }
    }

    if (col.renderCell) return col.renderCell(val, row);

    if (col.id === 'index') return (page * size) + idx + 1;

    // Standard Photo Rendering (SOP Compliance with Hover Zoom & Enlargement)
    if (col.id === 'photo' || col.id === 'employeePhotoUpload' || col.id === 'avatar') {
      const photoUrl = getPhotoUrl(val);
      return (
        <Tooltip
          placement="right"
          arrow
          enterDelay={150}
          leaveDelay={0}
          componentsProps={{
            tooltip: {
              sx: {
                bgcolor: 'background.paper',
                color: 'text.primary',
                boxShadow: '0px 10px 30px rgba(0, 0, 0, 0.15)',
                border: '1px solid',
                borderColor: 'divider',
                p: 0.5,
                borderRadius: '12px',
                maxWidth: 'none'
              }
            }
          }}
          title={
            photoUrl && val && val !== '-' && val !== 'null' && val !== 'undefined' ? (
              <Box
                component="img"
                src={photoUrl}
                alt="Enlarged Photo"
                sx={{
                  width: 140,
                  height: 175,
                  objectFit: 'contain',
                  display: 'block',
                  borderRadius: '8px'
                }}
              />
            ) : (
              <Typography variant="caption" sx={{ p: 1, display: 'block' }}>No Photo Available</Typography>
            )
          }
        >
          <Avatar
            src={photoUrl}
            variant="rounded"
            sx={{
              width: 32,
              height: 40,
              bgcolor: 'grey.100',
              border: '1px solid',
              borderColor: 'divider',
              cursor: 'pointer',
              transition: 'transform 0.15s ease-in-out',
              '&:hover': {
                transform: 'scale(1.15)',
                boxShadow: 2
              }
            }}
          >
            <IconUser size={18} color="#ccc" />
          </Avatar>
        </Tooltip>
      );
    }

    if (col.id === 'status' || col.id === 'accountStatus') {
      const statusText = getCellDisplayValue(col, row, idx);
      return <Chip label={statusText} size="small" sx={getStatusChipSx(statusText)} />;
    }

    const isDateField = (col.id.toLowerCase().includes('date') || 
                        col.id.endsWith('At') || 
                        col.id.endsWith('_at') || 
                        col.id === 'entryDate' ||
                        col.id === 'invoiceDate') &&
                        !col.id.toLowerCase().includes('by');
    
    // Explicitly exclude false positives like 'state' or 'category'
    const isFalsePositive = col.id.toLowerCase().includes('state') || col.id.toLowerCase().includes('category');

    if (isDateField && !isFalsePositive) {
      return formatDate(val);
    }
    
    // Handle Boolean values (Yes/No)
    if (typeof val === 'boolean') return val ? 'Yes' : 'No';
    
    if (typeof val === 'object' && val !== null) {
      return val.name || val.label || val.id || '-';
    }
    return (val !== null && val !== undefined && val !== '') ? String(val) : '-';
  };

  const activeSelectedId = selectedRowId !== undefined && selectedRowId !== null ? selectedRowId : localSelectedId;

  const { 
    height = 'calc(100vh - 215px)', 
    maxHeight, 
    minHeight, 
    ...restSx 
  } = sx;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height, maxHeight, minHeight, overflow: 'hidden' }}>
      <TableContainer component={Paper} sx={{ ...tableContainerSx, flexGrow: 1, height: '100%', borderBottomLeftRadius: 0, borderBottomRightRadius: 0, ...restSx }} id={id}>
        <Table stickyHeader size="small">
          <TableHead>
            <TableRow>
              {columns.map((col, ci) => (
                <TableCell
                  key={col.id}
                  align={col.align || 'left'}
                  sx={{
                    ...tableHeadCellSx,
                    ...(ci === 0 ? { borderTopLeftRadius: '16px' } : {}),
                    ...(!showActions && ci === columns.length - 1 ? { borderTopRightRadius: '16px' } : {})
                  }}
                >
                  {col.id === 'index' ? 'No' : col.label}
                </TableCell>
              ))}
              {showActions && (
                <TableCell sx={{ ...tableHeadCellSx, textAlign: 'center', borderTopRightRadius: '16px' }}>
                  Actions
                </TableCell>
              )}
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={columns.length + (showActions ? 1 : 0)} sx={{ p: 0, border: 'none' }}>
                  <Box sx={{ position: 'sticky', left: 0, width: '100%', maxWidth: 'calc(100vw - 280px)', display: 'flex', justifyContent: 'center', py: 3 }}>
                    <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>Loading data...</Typography>
                  </Box>
                </TableCell>
              </TableRow>
            ) : (filteredRows?.length || 0) === 0 ? (
              <TableRow>
                <TableCell colSpan={columns.length + (showActions ? 1 : 0)} sx={{ p: 0, border: 'none' }}>
                  <Box sx={{ position: 'sticky', left: 0, width: '100%', maxWidth: 'calc(100vw - 280px)', display: 'flex', justifyContent: 'center', py: 3 }}>
                    <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>No records found.</Typography>
                  </Box>
                </TableCell>
              </TableRow>
            ) : (
              paginatedRows.map((row, idx) => {
                const rowId = row.id !== undefined && row.id !== null ? row.id : `row-idx-${idx}`;
                const isSelected = Array.isArray(activeSelectedId)
                  ? activeSelectedId.includes(row.id) || activeSelectedId.includes(rowId)
                  : activeSelectedId === rowId || activeSelectedId === row.id;
                
                const rowSx = {
                  cursor: 'pointer',
                  transition: 'all 0.2s',
                  bgcolor: isSelected 
                    ? (isDark ? alpha(theme.palette.primary.main, 0.25) : alpha(theme.palette.primary.main, 0.12))
                    : (idx % 2 === 1 ? (isDark ? '#161b22' : '#fafafa') : (isDark ? 'background.paper' : '#ffffff')),
                  '& td': { 
                    borderBottom: '1px solid', 
                    borderColor: isSelected ? theme.palette.primary.main : 'divider', 
                    py: 1.5 // Ensure padding doesn't shrink!
                  },
                  '&:hover': {
                    bgcolor: isSelected 
                      ? (isDark ? alpha(theme.palette.primary.main, 0.3) : alpha(theme.palette.primary.main, 0.16)) + ' !important'
                      : (isDark ? alpha(theme.palette.primary.main, 0.15) : alpha(theme.palette.primary.main, 0.05)) + ' !important'
                  }
                };

                const showEditTooltip = Boolean(onDoubleClickRow || onEditRow);
                const isDoubleTapSupported = showEditTooltip;
                const rowElement = (
                  <TableRow 
                    key={rowId}
                    hover 
                    title={showEditTooltip ? "Double Tap To Edit" : undefined}
                    sx={rowSx} 
                    onClick={() => {
                      setLocalSelectedId(rowId);
                      onClickRow?.(row);
                    }}
                    onDoubleClick={() => onDoubleClickRow ? onDoubleClickRow(row) : (onEditRow ? onEditRow(row) : null)}
                    onMouseEnter={(e) => onRowMouseEnter?.(e, row)}
                    onMouseLeave={(e) => onRowMouseLeave?.(e, row)}
                    onMouseMove={(e) => onRowMouseMove?.(e, row)}
                  >
                  {columns.map((col) => (
                    <TableCell
                      key={col.id}
                      align={col.align || 'left'}
                      sx={{
                        cursor: (onDoubleClickRow || onClickRow || onEditRow) ? 'pointer' : 'default',
                        ...(col.id === 'index' ? { color: isSelected ? 'primary.dark' : 'primary.main', fontWeight: 600 } : {}),
                        ...(col.bold ? { fontWeight: 600, color: '#37474f' } : {}),
                        // SOP: Prevent column split issue by keeping text on one line unless explicitly long
                        whiteSpace: (String(resolveNestedValue(col.id, row) || '').length > 50 || col.wrap) ? 'normal' : 'nowrap',
                        ...(col.maxWidth ? { maxWidth: col.maxWidth, overflow: 'hidden', textOverflow: 'ellipsis' } : {}),
                        minWidth: col.id === 'index' ? 60 : (col.minWidth || 100),
                        paddingX: 1.5
                      }}
                    >
                      {(() => {
                        if (renderCell) {
                          const customVal = renderCell(col, row, idx);
                          if (customVal !== null && customVal !== undefined) return customVal;
                        }
                        return defaultRenderCell(col, row, idx);
                      })()}
                    </TableCell>
                  ))}
                  {showActions && (
                    <TableCell align="center" sx={{ minWidth: 100 }}>
                      <Stack direction="row" justifyContent="center" spacing={1} sx={{ flexWrap: 'nowrap', alignItems: 'center' }}>
                        {actionColumn && actionColumn.render && (
                          <Box onClick={(e) => e.stopPropagation()} sx={{ display: 'flex', gap: 0.5 }}>
                            {actionColumn.render(row)}
                          </Box>
                        )}
                        {onEditRow && (
                          <Tooltip title="Edit">
                            <IconButton onClick={(e) => { e.stopPropagation(); onEditRow(row); }} size="small" sx={tableActionEditSx}>
                              <IconEdit size={16} />
                            </IconButton>
                          </Tooltip>
                        )}
                        {onDeleteRow && (
                          <Tooltip title="Delete">
                            <IconButton onClick={(e) => { e.stopPropagation(); onDeleteRow(row); }} size="small" sx={tableActionDeleteSx}>
                              <IconTrash size={16} />
                            </IconButton>
                          </Tooltip>
                        )}
                      </Stack>
                    </TableCell>
                  )}
                </TableRow>
                );

                return isDoubleTapSupported ? (
                  <Tooltip key={rowId} title="Double Tap" followCursor placement="top" arrow>
                    {rowElement}
                  </Tooltip>
                ) : (
                  React.cloneElement(rowElement, { key: rowId })
                );
              })
            )}
          </TableBody>
        </Table>
      </TableContainer>
      <Box sx={{ 
        py: 0, 
        px: 1.5, 
        minHeight: '36px',
        height: '36px',
        display: 'grid',
        gridTemplateColumns: '1fr auto 1fr',
        alignItems: 'center',
        borderTop: '1px solid', 
        borderColor: 'divider',
        bgcolor: isDark ? 'background.default' : 'grey.50',
        borderBottomLeftRadius: '16px',
        borderBottomRightRadius: '16px'
      }}>
        <Box sx={{ display: 'flex', justifyContent: 'flex-start', alignItems: 'center' }}>
          {footerActions}
        </Box>
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <TablePagination
            rowsPerPageOptions={[5, 10, 25, 50]}
            component="div"
            count={totalCount ?? (rows?.length || 0)}
            rowsPerPage={size}
            page={page}
            onPageChange={(e, p) => onPageChange(p)}
            onRowsPerPageChange={(e) => onSizeChange(parseInt(e.target.value, 10))}
            sx={{
              minHeight: '36px !important',
              height: '36px !important',
              overflow: 'hidden',
              border: 'none',
              '& .MuiTablePagination-toolbar': { 
                justifyContent: 'center', 
                flexWrap: 'nowrap',
                minHeight: '36px !important',
                height: '36px',
                p: '0px !important',
                gap: 1
              },
              '& .MuiTablePagination-spacer': { display: 'none' },
              '& .MuiTablePagination-selectLabel, & .MuiTablePagination-displayedRows': {
                margin: 0,
                fontSize: '0.75rem',
                fontWeight: 500
              },
              '& .MuiTablePagination-select': {
                py: '2px',
                fontSize: '0.75rem',
                fontWeight: 500
              },
              '& .MuiTablePagination-actions': {
                margin: 0
              }
            }}
          />
        </Box>
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }} />
      </Box>
    </Box>
  );
}

