import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';

// material-ui
import { useTheme } from '@mui/material/styles';
import Avatar from '@mui/material/Avatar';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Chip from '@mui/material/Chip';
import ClickAwayListener from '@mui/material/ClickAwayListener';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import InputAdornment from '@mui/material/InputAdornment';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import OutlinedInput from '@mui/material/OutlinedInput';
import Paper from '@mui/material/Paper';
import Popper from '@mui/material/Popper';
import Stack from '@mui/material/Stack';
import Switch from '@mui/material/Switch';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';

// third party
import { FormattedMessage } from 'react-intl';

// project imports
import MainCard from 'ui-component/cards/MainCard';
import Transitions from 'ui-component/extended/Transitions';
import useAuth from 'hooks/useAuth';
import useLookups from 'hooks/useLookups';
import { getUserImageUrl } from 'utils/upload-helper';
import axios from 'utils/axios'; // Or standard axios if utils/axios is not present, let's just use regular axios or the one from 'utils/axios'

// assets
import User1 from 'assets/images/users/avatar-1.png';
import { IconLogout, IconSearch, IconSettings, IconUser } from '@tabler/icons-react';
import useConfig from 'hooks/useConfig';

// ==============================|| PROFILE MENU ||============================== //

function getGreeting() {
  const h = new Date().getHours();
  if (h < 12) return 'Good Morning,';
  if (h < 17) return 'Good Afternoon,';
  return 'Good Evening,';
}

export default function ProfileSection() {
  const theme = useTheme();
  const {
    state: { borderRadius },
    setCustomizationOpen
  } = useConfig();
  const navigate = useNavigate();

  const [sdm, setSdm] = useState(true);
  const [value, setValue] = useState('');
  const [notification, setNotification] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const { logout, user } = useAuth();
  const { departments = [], designations = [], levels = [], designationLevels = [] } = useLookups(['DEPARTMENTS', 'DESIGNATIONS', 'LEVELS', 'DESIGNATION_LEVELS']);
  const finalLevels = levels.length > 0 ? levels : designationLevels;
  const [open, setOpen] = useState(false);

  const [empInfo, setEmpInfo] = useState('Loading...');

  useEffect(() => {
    if (user) {
      axios.get('/api/master/hr/employees')
        .then(res => {
          const allEmps = res.data || [];
          const empRecord = allEmps.find(e =>
            (e.id && user.empId && String(e.id) === String(user.empId)) ||
            (e.empCode && user.empCode && String(e.empCode) === String(user.empCode))
          );
          if (empRecord) {
            const getDesigName = (id, fallback) => String(designations.find(d => String(d.id) === String(id))?.designationName || fallback || '');
            const getDeptName = (id, fallback) => String(departments.find(d => String(d.id) === String(id))?.departmentName || fallback || '');
            const getLevelName = (id, fallback) => {
              const match = (finalLevels || []).find(l => String(l.rowId || l.id) === String(id));
              return String(match?.level || match?.levelName || fallback || '');
            };

            const desig = empRecord.designationId ? getDesigName(empRecord.designationId, empRecord.designationName || empRecord.designation) : (user.designation?.name || user.designation || empRecord.designationName || empRecord.designation || '');
            const dept = empRecord.departmentId ? getDeptName(empRecord.departmentId, empRecord.departmentName || empRecord.department) : (user.department?.name || user.department || empRecord.departmentName || empRecord.department || '');
            const level = empRecord.empLevelId ? getLevelName(empRecord.empLevelId, empRecord.levelName || empRecord.level) : '';

            const combinedText = (level ? `${level} - ` : '') + [desig, dept].filter(Boolean).join(' / ');
            setEmpInfo(combinedText.toUpperCase() || 'USER');
          } else {
            const desig = user.designation?.name || user.designation || '';
            const dept = user.department?.name || user.department || '';
            const combinedText = [desig, dept].filter(Boolean).join(' / ');
            setEmpInfo(combinedText.toUpperCase() || 'USER');
          }
        })
        .catch(err => {
          console.error(err);
          setEmpInfo('USER');
        });
    }
  }, [user, departments, designations, levels]);

  /**
   * anchorRef is used on different components and specifying one type leads to other components throwing an error
   * */
  const anchorRef = useRef(null);
  const handleLogout = async () => {
    try {
      await logout();
    } catch (err) {
      console.error(err);
    }
  };

  const handleListItemClick = (event, index, route = '') => {
    setSelectedIndex(index);
    handleClose(event);

    if (route && route !== '') {
      navigate(route);
    }
  };

  const handleToggle = () => {
    setOpen((prevOpen) => !prevOpen);
  };

  const handleClose = (event) => {
    if (anchorRef.current && anchorRef.current.contains(event.target)) {
      return;
    }

    setOpen(false);
  };

  const prevOpen = useRef(open);
  useEffect(() => {
    if (prevOpen.current === true && open === false) {
      anchorRef.current.focus();
    }

    prevOpen.current = open;
  }, [open]);

  return (
    <>
      <Stack
        direction="row"
        sx={{
          ml: 2,
          height: '48px',
          alignItems: 'center',
          borderRadius: '27px',
          bgcolor: theme.palette.primary.main,
          px: 1,
          gap: 1
        }}
      >
        <Avatar
          src={user?.imgName ? getUserImageUrl(user.imgName) : User1}
          alt="user-images"
          sx={{
            typography: 'mediumAvatar',
            cursor: 'pointer',
            width: 34,
            height: 34,
            transition: 'all 0.2s ease-in-out',
            '&:hover': { transform: 'scale(1.05)', boxShadow: '0 0 8px rgba(255,255,255,0.5)' }
          }}
          ref={anchorRef}
          aria-controls={open ? 'menu-list-grow' : undefined}
          aria-haspopup="true"
          onClick={handleToggle}
        />
        <IconButton
          color="inherit"
          onClick={() => setCustomizationOpen(true)}
          sx={{
            p: 0.5,
            color: '#fff',
            '&:hover': { bgcolor: 'rgba(255,255,255,0.1)' }
          }}
          aria-label="live-customize"
        >
          <IconSettings stroke={1.5} size="24px" />
        </IconButton>
      </Stack>
      <Popper
        placement="bottom"
        open={open}
        anchorEl={anchorRef.current}
        role={undefined}
        transition
        disablePortal
        modifiers={[
          {
            name: 'offset',
            options: {
              offset: [0, 14]
            }
          }
        ]}
      >
        {({ TransitionProps }) => (
          <ClickAwayListener onClickAway={handleClose}>
            <Transitions in={open} {...TransitionProps}>
              <Paper>
                {open && (
                  <MainCard border={false} elevation={16} content={false} boxShadow shadow={theme.shadows[16]}>
                    <Box sx={{ p: 2, pb: 0 }}>
                      <Stack spacing={0.5}>
                        <Stack direction="row" sx={{ alignItems: 'baseline', gap: 0.75 }}>
                          <Typography variant="h4" sx={{ color: '#f5d60bff', fontWeight: 600 }}>
                            {getGreeting()}
                          </Typography>
                          <Typography variant="h3" sx={{ fontWeight: 800, color: 'primary.main' }}>
                            {user?.name}
                          </Typography>
                        </Stack>
                        <Typography variant="subtitle2" sx={{ mt: 0.5 }}>
                          {empInfo}
                        </Typography>
                      </Stack>
                      <Divider sx={{ mt: 2 }} />
                    </Box>
                    <Box
                      sx={{
                        p: 2,
                        py: 0,
                        height: '100%',
                        maxHeight: 'calc(100vh - 250px)',
                        overflowX: 'hidden',
                        '&::-webkit-scrollbar': { width: 5 }
                      }}
                    >
                      <Divider sx={{ display: 'none' }} />
                      <Card sx={{ bgcolor: 'primary.light', ...theme.applyStyles('dark', { bgcolor: 'dark.800' }), my: 2 }}>
                        <CardContent>
                          <Stack sx={{ gap: 3 }}>
                            <Stack direction="row" sx={{ alignItems: 'center', justifyContent: 'space-between' }}>
                              <Typography variant="subtitle1">Start DND Mode</Typography>
                              <Switch color="primary" checked={sdm} onChange={(e) => setSdm(e.target.checked)} name="sdm" size="small" />
                            </Stack>
                            <Stack direction="row" sx={{ alignItems: 'center', justifyContent: 'space-between' }}>
                              <Typography variant="subtitle1">Allow Notifications</Typography>
                              <Switch checked={notification} onChange={(e) => setNotification(e.target.checked)} name="sdm" size="small" />
                            </Stack>
                          </Stack>
                        </CardContent>
                      </Card>
                      <Divider />
                      <List
                        component="nav"
                        sx={{
                          width: '100%',
                          maxWidth: 350,
                          minWidth: 300,
                          borderRadius: `${borderRadius}px`,
                          '& .MuiListItemButton-root': { mt: 0.5 }
                        }}
                      >
                        <ListItemButton
                          sx={{ borderRadius: `${borderRadius}px` }}
                          selected={selectedIndex === 0}
                          onClick={(event) => handleListItemClick(event, 0, '/apps/user/account-profile/profile1')}
                        >
                          <ListItemIcon>
                            <IconSettings stroke={1.5} size="20px" />
                          </ListItemIcon>
                          <ListItemText
                            primary={
                              <Typography variant="body2">
                                <FormattedMessage id="account-settings" />
                              </Typography>
                            }
                          />
                        </ListItemButton>
                        <ListItemButton
                          sx={{ borderRadius: `${borderRadius}px` }}
                          selected={selectedIndex === 1}
                          onClick={(event) => handleListItemClick(event, 1, '/apps/user/social-profile/posts')}
                        >
                          <ListItemIcon>
                            <IconUser stroke={1.5} size="20px" />
                          </ListItemIcon>
                          <ListItemText
                            primary={
                              <Stack direction="row" sx={{ alignItems: 'center', justifyContent: 'space-between' }}>
                                <Typography variant="body2">
                                  <FormattedMessage id="social-profile" />
                                </Typography>
                                <Chip
                                  slotProps={{
                                    label: { sx: { mt: 0.25, ...theme.applyStyles('dark', { color: 'background.default' }) } }
                                  }}
                                  label="02"
                                  variant="filled"
                                  size="small"
                                  color="warning"
                                />
                              </Stack>
                            }
                          />
                        </ListItemButton>
                        <ListItemButton sx={{ borderRadius: `${borderRadius}px` }} selected={selectedIndex === 4} onClick={handleLogout}>
                          <ListItemIcon>
                            <IconLogout stroke={1.5} size="20px" />
                          </ListItemIcon>
                          <ListItemText
                            primary={
                              <Typography variant="body2">
                                <FormattedMessage id="logout" />
                              </Typography>
                            }
                          />
                        </ListItemButton>
                      </List>
                    </Box>
                  </MainCard>
                )}
              </Paper>
            </Transitions>
          </ClickAwayListener>
        )}
      </Popper>
    </>
  );
}
